code.java:
public int sumOfDigits(int n) {
    n = Math.abs(n);
    int sum = 0;
    while (n > 0) {
        sum += n % 10;   // last digit
        n /= 10;         // drop it
    }
    return sum;
}

public int digitalRoot(int n) {
    n = Math.abs(n);
    if (n == 0) {
        return 0;
    }
    return 1 + (n - 1) % 9;
}

